let lang=localStorage.getItem('materials-language')||'zh', page='dashboard', selectedContract='', selectedSegment='', db=null, token='', upload=null, preview=null, importKind='IN', cart=[], deleteSelected=[], action='OUT', posting=false, outKey=crypto.randomUUID(), treeState={query:'',contract:'',batch:'',warehouse:'',state:'',sort:'contract'};
const $=id=>document.getElementById(id), t=(zh,en)=>lang==='zh'?zh:en;
const APP_VERSION='0.1.1';
function setOnline(ok){const dot=document.querySelector('.side-foot .dot');if(dot)dot.classList.toggle('err',!ok);}
async function boot(){try{await refresh();}catch(e){offlineShell(e);}}
function offlineShell(e){
 const v=$('version');if(v)v.textContent=APP_VERSION;
 $('view').innerHTML=`<div class="panel"><div class="empty"><strong>${t('无法连接本地服务','Cannot reach the local service')}</strong><p>${t('请确认已运行 启动系统.cmd，然后点击右上角“刷新”。','Run 启动系统.cmd and click Refresh (top-right).')}</p><p class="sub">${esc(e?.message||'')}</p></div></div>`;
 notice(t('无法连接本地服务，请确认已运行 启动系统.cmd。','Cannot reach the local service. Please run 启动系统.cmd.'),true);
}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v===null||v===undefined?'—':Number(v).toLocaleString(lang==='zh'?'zh-CN':'en-GB',{maximumFractionDigits:6});
const states={AVAILABLE:['可用','Available'],PENDING:['待检','Pending inspection'],QUARANTINE:['隔离','Quarantine'],SPARE:['预留备品','Reserved spares'],PLANNED:['待发运','Planned'],DISPATCHED:['已发运','Dispatched'],SEA:['海运中','At sea'],CUSTOMS:['清关中','Customs'],RELEASED:['已放行','Released'],ROAD:['陆运中','Road transit'],ARRIVED:['已到场','Arrived'],IN:['入库单','Goods receipt'],OUT:['出库单','Goods issue'],HANDOVER:['备品移交单','Spares handover'],MOVE:['移库单','Bin transfer'],STATE:['库存状态调整单','Stock status change'],REV:['冲销单','Reversal'],BASELINE:['设计基准单','Design baseline']};
const label=k=>states[k]?t(...states[k]):k;
const badge=k=>`<span class="tag ${esc(k)}">${esc(label(k))}</span>`;
const segmentByCode=code=>(db?.segments||[]).find(s=>s.code===code);
const segmentLabel=code=>{const s=segmentByCode(code);return s?`${s.code}｜${lang==='zh'?s.zh:s.en}`:(code||'—');};
const segmentOptions=(selected='')=>`<option value="">${t('请选择标段','Select segment')}</option>`+(db?.segments||[]).map(s=>`<option value="${esc(s.code)}" ${s.code===selected?'selected':''}>${esc(s.code)}｜${esc(lang==='zh'?s.zh:s.en)}</option>`).join('');
const segmentIndex=code=>{const i=(db?.segments||[]).findIndex(s=>s.code===code);return i<0?999:i;};
function stockBalance(row){
 if(row&&row.received_total!==undefined&&row.received_total!==null){
  return {total:Number(row.received_total||0),available:Number(row.available_qty||0)};
 }
 const key=x=>[x?.code||'',x?.batch||'',x?.box||'',x?.package||''].join('\u001f');
 const rowKey=key(row), docs=new Set((db?.documents||[]).filter(d=>!d.reversed_by).map(d=>Number(d.id)));
 const receipts=(db?.ledger||[]).filter(x=>x.kind==='IN'&&docs.has(Number(x.doc_id))&&key(x)===rowKey);
 if(!receipts.length)return null;
 const total=receipts.reduce((sum,x)=>sum+Math.max(0,Number(x.delta||0)),0);
 const available=(db?.stock||[]).filter(x=>key(x)===rowKey&&x.state==='AVAILABLE').reduce((sum,x)=>sum+Number(x.qty||0),0);
 return {total,available};
}
function stockBalanceText(row){
 const balance=stockBalance(row), unit=esc(row.unit);
 if(!balance)return `${fmt(row.qty)} ${unit}`;
 return `${t('总量','Total')} ${fmt(balance.total)} ${unit} · ${t('剩余','Remaining')} ${fmt(balance.available)} ${unit}`;
}
const fields={code:['物资编码 *','Item code *'],name:['物资名称 *','Item name *'],spec:['规格型号','Specification'],unit:['单位 *','Unit *'],qty:['数量 *','Quantity *'],batch:['到货批次','Arrival batch'],box:['箱号','Box no.'],warehouse:['仓库','Warehouse'],bin:['库位','Bin'],state:['库存状态','Stock status'],package:['标段','Segment'],attribute:['设备属性','Equipment attribute']};
function notice(s,error=false){$('notice').hidden=false;$('notice').className=error?'error':'';$('notice').textContent=s;}
async function api(path,p){let r;try{r=await fetch(path,p?{method:'POST',headers:{'Content-Type':'application/json','X-Local-Token':token},body:JSON.stringify(p)}:{});}catch{throw Error(t('无法连接本地服务，请确认已运行 启动系统.cmd。','Cannot reach the local service. Please run 启动系统.cmd.'));}let data;try{data=await r.json();}catch{throw Error(t('服务响应异常，请刷新重试。','Unexpected server response. Refresh and retry.'));}if(!r.ok)throw Error(data.error||r.statusText);return data;}
async function refresh(render=true){try{db=await api('/api/state');token=db.token;setOnline(true);if($('notice'))$('notice').hidden=true;if(render)draw();}catch(e){setOnline(false);throw e;}}
function options(keys,selected){return keys.map(k=>`<option value="${esc(k)}" ${k===selected?'selected':''}>${esc(label(k))}</option>`).join('');}
function input(id,title,value='',type='text',extra=''){
 const field=id.endsWith('warehouse')?'warehouse':id.endsWith('bin')?'bin':null;
 const vals=field?[...new Set((db?.stock||[]).map(s=>s[field]))]:[];
 const choices=field?`<datalist id="${id}-choices">${vals.map(v=>`<option value="${esc(v)}"></option>`).join('')}</datalist>`:'';
 return `<label>${esc(title)}<input id="${id}" type="${type}" value="${esc(value)}" ${extra} ${field?`list="${id}-choices"`:''}></label>${choices}`;
}
function empty(title,desc){return `<div class="empty"><strong>${title}</strong>${desc}</div>`;}
function table(head,rows){return `<div class="table-wrap"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
function draw(){
 document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.title=t('智能仓储系统 · 本地试用版','Intelligent Warehouse System · Local Trial');
 const pages=[['dashboard','项目总览','Project overview'],['inbound','入库办理','Receipts'],['outbound','出库办理','Issues'],['inventory','仓库明细','Warehouse detail'],['items','物资总表','Materials table'],['ledger','流水总账','Transaction ledger'],['spares','备品情况','Spares'],['documents','单据查询','Documents'],['delete','删除办理','Admin deletion']];
 $('nav').innerHTML=pages.map((p,i)=>`<button data-page="${p[0]}" class="${page===p[0]?'active':''}"><span>0${i+1}</span><span>${t(p[1],p[2])}</span></button>`).join('');
 $('title').textContent=t(...pages.find(p=>p[0]===page).slice(1));$('brand-name').firstChild.textContent=t('智能仓储系统','Intelligent Warehouse System');$('brand-sub').textContent=t('面向新能源 EPC 的全流程物资管理','End-to-end materials control for renewable EPC');$('mode').textContent=t('本机试用 · 数据集中保存','Local trial · Central ledger');$('mode-note').textContent=t('先跑通收发，再开放协作','Validate transactions before collaboration');$('footer').textContent=t('智能仓储系统 · 所有库存变动均有单据依据','Intelligent Warehouse System · Every stock movement has a document');$('lang').textContent=lang==='zh'?'English':'中文';$('refresh').textContent=t('刷新','Refresh');$('close-modal').textContent=t('关闭','Close');if($('version'))$('version').textContent=db?.version||APP_VERSION;
 $('view').innerHTML=page==='dashboard'?dashboard():page==='inventory'?overview():page==='items'?materialsOverview():page==='inbound'?inbound():page==='outbound'?outbound():page==='ledger'?ledgerPage():page==='spares'?sparesPage():page==='delete'?deletePage():documents();
 if(page==='inventory'){simplifyBatchStatus();renderInventoryTree();}
 if(page==='inbound'){enhanceBatchForm();ensureDefaultBox();simplifyInboundForm();fixTemplateLink();}
 if(page==='inbound'&&preview){renderPreview();}
}
function fixTemplateLink(){const a=document.querySelector('a[href="/api/template"]');if(a){a.href=importKind==='BASELINE'?'/api/template':'/api/supplier-template';a.textContent=importKind==='BASELINE'?t('下载设计数量示例 CSV','Download baseline CSV'):t('下载厂家固定模板','Download supplier template');}}
function ensureDefaultBox(){const wh=$('default-warehouse');if(wh&&!$('default-box'))wh.closest('label').insertAdjacentHTML('beforebegin',input('default-box',t('默认箱号（表格没有箱号时填写）','Default box no. (only if sheet has none)')));}
function simplifyInboundForm(){
 const grid=document.querySelector('#view .form-grid');if(!grid||grid.querySelector('.advanced-defaults'))return;
 const ids=['default-box','default-state','header'];
 const fields=ids.map(id=>$(id)?.closest('label')).filter(Boolean);if(!fields.length)return;
 const details=document.createElement('details');details.className='advanced-defaults';
 const summary=document.createElement('summary');summary.textContent=t('高级：箱号、库存状态和表头（通常不用修改）','Advanced: box, stock status and header (usually not needed)');details.append(summary);
 grid.append(details);fields.forEach(label=>details.append(label));
 const helper=document.createElement('p');helper.className='helper';helper.textContent=t('批次由系统自动生成；厂家箱单没有仓库和库位时，整张表使用上面选择的位置。','The batch is generated automatically. If the factory sheet has no warehouse or bin, the selected location above applies to the whole sheet.');grid.append(helper);
}
function todayISO(){return new Date().toISOString().slice(0,10);}
function inferDeviceLabel(r){
 const text=[r?.rows?.find(x=>x.box)?.box,r?.rows?.find(x=>x.name)?.name,upload?.filename].filter(Boolean).join(' ');
 const matches=[['无人机机场','无人机机场'],['轨道机器人','轨道机器人'],['轮式机器人','轮式机器人'],['水浸传感器','水浸传感器'],['摄像头','摄像头'],['电池','电池'],['支架','支架'],['组件','组件']];
 return matches.find(([needle])=>text.includes(needle))?.[1]||'设备';
}
function autoFillReceiptDefaults(r){
 if(!r||!$('batch-date'))return;
 if(!$('batch-date').value)$('batch-date').value=todayISO();
 const wh=$('default-warehouse');if(wh&&!wh.value)wh.value='主仓库';
 const bin=$('default-bin');if(bin&&!bin.value)bin.value='待分配';
 const b=$('batch-preview');if(b)b.textContent=composeBatch();
}
function enhanceBatchForm(){
 const old=$('default-batch'); if(!old||$('batch-date'))return;
 const label=old.closest('label');
 if(importKind==='BASELINE'){label.hidden=true;return;}
 label.outerHTML=`<div class="batch-fields"><label>${t('到货日期','Arrival date')}<input id="batch-date" type="date" value="${esc(upload?.batchDate||todayISO())}"></label><label>${t('批次序号','Batch number')}<input id="batch-number" type="number" min="1" value="${esc(upload?.batchNumber||'1')}"></label><div class="batch-preview"><span>${t('到货批次','Arrival batch')}</span><b id="batch-preview">${esc(composeBatch())||t('填写批次序号后生成','Enter a batch number to generate')}</b></div></div>`;
 const b=$('batch-preview');if(b)b.textContent=composeBatch();
 }
function composeBatch(){const field=$('batch-number');const batch=field?(field.value||'').trim():(upload?.batchNumber||'1');if(!batch)return '';return `B${batch.padStart(2,'0').slice(-2)}`;}
function simplifyBatchStatus(){const panel=[...document.querySelectorAll('#view details')].find(d=>d.querySelector('summary')?.textContent.includes('发运批次'));if(!panel)return;const helper=panel.querySelector('.helper');if(helper)helper.textContent=t('物流状态手动选择并留痕；不会改变库存数量。到货批次只用于入库及追溯；出库使用独立出库单号。','Transport status changes are logged and do not alter quantities. Arrival batch is for receipt traceability; issue uses its own number.');const code=$('batch-code');const label=code?.closest('label');if(label&&label.firstChild)label.firstChild.textContent=t('到货批次号 *','Arrival batch *');panel.querySelectorAll('th').forEach(th=>{if(th.textContent.trim()==='合同批次')th.textContent=t('到货批次','Arrival batch');});}
function dateText(v){return v?v.slice(0,10):'—';}
function dateRange(first,last){if(!first&&!last)return '—';if(first===last)return dateText(first);return `${dateText(first)} ~ ${dateText(last)}`;}
function qtySummary(g,key){const totals=g.unit_totals||{};const vals=Object.entries(totals).map(([unit,v])=>[unit,v[key]]).filter(([,v])=>v!==undefined&&v!==null&&v!==0);return vals.length?vals.map(([unit,v])=>`${fmt(v)} ${esc(unit)}`).join(' / '):'—';}
function pctSummary(g,key){const totals=g.unit_totals||{};const vals=Object.entries(totals).map(([unit,v])=>{const total=Number(v.current||0),value=Number(v[key]||0);return total>0?`${fmt(value/total*100)}% ${esc(unit)}`:'';}).filter(Boolean);return vals.length?vals.join(' / '):t('待设定','Not set');}
function groupRows(rows,key){const groups=new Map();rows.forEach(row=>{const value=key(row)||'—';if(!groups.has(value))groups.set(value,[]);groups.get(value).push(row);});return [...groups].map(([key,rows])=>({key,rows}));}
function unitSummaryRows(rows){const totals={};rows.forEach(row=>{const unit=row.unit||'—';totals[unit]=(totals[unit]||0)+Number(row.qty||0);});return Object.entries(totals).map(([unit,qty])=>`${fmt(qty)} ${esc(unit)}`).join(' / ')||'—';}
function treeSort(groups,level){const sort=treeState.sort;return groups.sort((a,b)=>{if(sort==='qty')return b.rows.reduce((n,r)=>n+Number(r.qty||0),0)-a.rows.reduce((n,r)=>n+Number(r.qty||0),0);if(level==='contract'){const ai=segmentIndex(a.key),bi=segmentIndex(b.key);if(ai!==999||bi!==999)return ai-bi;}return a.key.localeCompare(b.key,'zh-CN');});}
function filteredTreeRows(){const q=(treeState.query||'').trim().toLowerCase();return (db.stock||[]).filter(row=>{const childText=Array.isArray(row.contents)?row.contents.flatMap(child=>Object.values(child)):[];const hay=[...Object.values(row),...childText].join(' ').toLowerCase();return (!q||hay.includes(q))&&(!treeState.contract||row.package===treeState.contract)&&(!treeState.batch||row.batch===treeState.batch)&&(!treeState.warehouse||row.warehouse===treeState.warehouse)&&(!treeState.state||row.state===treeState.state);});}
function treeLeaf(row){return `<div class="tree-leaf"><div><span class="code">${esc(row.code)}</span><br><span class="name">${esc(row.name)}</span>${row.spec?`<span class="sub"> · ${esc(row.spec)}</span>`:''}${row.attribute?`<div class="sub">${esc(row.attribute)}</div>`:''}</div><div class="tree-leaf-right"><span>${stockBalanceText(row)}</span>${badge(row.state)}</div></div>`;}
function treeBoxHtml(box){const rows=[...box.rows].sort((a,b)=>treeState.sort==='item'?`${a.name}${a.code}`.localeCompare(`${b.name}${b.code}`,'zh-CN'):treeState.sort==='qty'?Number(b.qty)-Number(a.qty):`${a.code}`.localeCompare(`${b.code}`,'zh-CN'));const locations=[...new Set(rows.map(row=>row.warehouse+'/'+row.bin))].join(' / ');return `<details class="tree-box"><summary><span class="tree-title">${esc(box.key)}</span><span class="tree-meta">${rows.length} ${t('项','items')} · ${unitSummaryRows(rows)} · ${esc(locations)}</span></summary><div class="tree-leaves">${rows.map(treeLeaf).join('')}</div></details>`;}
function treeBatchHtml(batch){const boxes=treeSort(groupRows(batch.rows,row=>row.box||'未分配箱号'),'box');return `<details class="tree-batch"><summary><span class="tree-title">${esc(batch.key)}</span><span class="tree-meta">${boxes.length} ${t('箱','boxes')} · ${unitSummaryRows(batch.rows)}</span></summary><div class="tree-level">${boxes.map(treeBoxHtml).join('')}</div></details>`;}
function treeContractHtml(contract){const batches=treeSort(groupRows(contract.rows,row=>row.batch||'未分配批次'),'batch');return `<details class="tree-contract" open><summary><span class="tree-title">${esc(segmentLabel(contract.key))}</span><span class="tree-meta">${contract.rows.length} ${t('条库存明细','stock lines')} · ${unitSummaryRows(contract.rows)}</span><button class="quiet small tree-contract-open" data-contract="${esc(contract.key)}">${t('单独查看','Open contract')}</button></summary><div class="tree-level">${batches.map(treeBatchHtml).join('')}</div></details>`;}
function inventoryTreeHTML(){const rows=filteredTreeRows();const contracts=treeSort(groupRows(rows,row=>row.package||'未指定标段'),'contract');const opts=(values,current,allLabel)=>`<option value="">${allLabel}</option>${values.map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(segmentLabel(v))}</option>`).join('')}`;const values=(key)=>{const current=(db.stock||[]).map(row=>row[key]).filter(Boolean);if(key==='package')current.push(...(db.segments||[]).map(s=>s.code));return [...new Set(current)].sort((a,b)=>key==='package'?(segmentIndex(a)-segmentIndex(b)||a.localeCompare(b,'zh-CN')):a.localeCompare(b,'zh-CN'));};const controls=`<div class="tree-filters"><input id="tree-search" class="search" value="${esc(treeState.query)}" placeholder="${t('搜索标段、批次、箱号、物资','Search lot, batch, box or item')}"><select id="tree-contract">${opts(values('package'),treeState.contract,t('全部标段','All segments'))}</select><select id="tree-batch">${opts(values('batch'),treeState.batch,t('全部批次','All batches'))}</select><select id="tree-warehouse">${opts(values('warehouse'),treeState.warehouse,t('全部仓库','All warehouses'))}</select><select id="tree-state">${opts(values('state'),treeState.state,t('全部状态','All states'))}</select><select id="tree-sort"><option value="contract" ${treeState.sort==='contract'?'selected':''}>${t('按标段排序','Sort by segment')}</option><option value="batch" ${treeState.sort==='batch'?'selected':''}>${t('按批次排序','Sort by batch')}</option><option value="box" ${treeState.sort==='box'?'selected':''}>${t('按箱号排序','Sort by box')}</option><option value="item" ${treeState.sort==='item'?'selected':''}>${t('按物资排序','Sort by item')}</option><option value="qty" ${treeState.sort==='qty'?'selected':''}>${t('按数量排序','Sort by quantity')}</option></select><button class="quiet small" data-tree-toggle="open">${t('全部展开','Expand all')}</button><button class="quiet small" data-tree-toggle="closed">${t('全部收起','Collapse all')}</button></div>`;if(!contracts.length)return controls+empty(t('没有符合条件的库存','No stock matches the filters'),t('调整筛选条件，或先确认一批入库。','Adjust the filters or post a receipt first.'));return controls+`<div class="tree">${contracts.map(treeContractHtml).join('')}</div>`;}
function renderInventoryTree(){const el=$('inventory-tree');if(!el)return;el.innerHTML=inventoryTreeHTML();const stateSelect=$('tree-state');if(stateSelect)[...stateSelect.options].forEach(option=>{if(option.value)option.textContent=label(option.value);});}
function contractIndex(){return `<section class="panel"><div class="panel-top"><div><h2>${t('标段 → 批次 → 箱号 → 箱内物资','Lot → Batch → Box → Contents')}</h2><p>${t('按物流层级查看库存；每一层都可以展开、收起、筛选和排序。','View stock by logistics level; each level can be expanded, collapsed, filtered and sorted.')}</p></div></div><div id="inventory-tree">${inventoryTreeHTML()}</div></section>`;}
function reconciliationPanel(){
 const audit=db?.reconciliation||{ok:true,issues:[]}, issues=audit.issues||[];
 const issueText=i=>i.kind==='ledger_mismatch'
  ? `${esc(i.code)} · ${t('库存位置与流水差异','Stock and ledger differ')} ${fmt(i.difference)} ${esc(i.unit||'')}`
  : i.kind==='over_contract'
   ? `${esc(i.code)} · ${t('累计入库超过合同/设计数量','Receipts exceed contract/design quantity')} ${fmt(i.difference)} ${esc(i.unit||'')}`
   : `${esc(i.code||'')} · ${t('需要核对','Needs review')}`;
 return `<section class="panel reconciliation-panel"><div class="panel-top"><div><h2>${t('账面核对','Ledger check')}</h2><p>${t('只检查并提示，不会自动修改库存。','Checks and alerts only; nothing is changed automatically.')}</p></div><span class="tag ${audit.ok?'AVAILABLE':'QUARANTINE'}">${audit.ok?t('核对通过','Check passed'):t(`${issues.length} 项异常`,` ${issues.length} issue(s)`)}</span></div>${audit.ok?`<div class="success-box">${t('流水、库存位置和合同数量目前一致。','Movements, stock positions and known contract quantities are consistent.')}</div>`:`<div class="warning-list">${issues.slice(0,8).map(issueText).join('<br>')}${issues.length>8?`<br>${t('其余异常请到流水总账查看。','Open the transaction ledger for the remaining issues.')}`:''}</div>`}</section>`;
}
function unitTotals(rows){const totals={};(rows||[]).forEach(r=>{const unit=r.unit||'—';totals[unit]=(totals[unit]||0)+Number(r.qty||0);});return Object.entries(totals).map(([unit,qty])=>`${fmt(qty)} ${esc(unit)}`).join(' / ')||'—';}
function dashboard(){
 if(selectedContract)return contractPage(selectedContract);
 const validDocs=db.documents.filter(d=>!d.reversed_by), inboundDocs=validDocs.filter(d=>d.kind==='IN'), outboundDocs=validDocs.filter(d=>d.kind==='OUT');
 const held=db.stock.filter(s=>['PENDING','QUARANTINE'].includes(s.state));
 const recent=validDocs.slice(0,6);
 const contractRows=(db.contracts||[]).filter(g=>segmentByCode(g.code)).sort((a,b)=>segmentIndex(a.code)-segmentIndex(b.code));
 const unmappedRows=(db.contracts||[]).filter(g=>!segmentByCode(g.code));
 return `<p class="intro">${t('领导视图：先看项目总量和异常，再进入入库、出库和仓库明细。','Leadership view: start with project totals and exceptions, then open receipts, issues and warehouse detail.')}</p>
 <div class="metrics">${[[contractRows.length,t('固定标段','Fixed segments'),t('A1-A16','A1-A16')],[db.stock.length,t('库存明细','Stock lines'),t('批次、箱号、库位','Batch, box and bin')],[inboundDocs.length,t('入库单','Receipt documents'),t('确认后自动更新库存','Postings update stock')],[outboundDocs.length,t('出库单','Issue documents'),t('独立单号，来源可追溯','Unique numbers, traceable sources')]].map(m=>`<div class="metric"><small>${m[1]}</small><b>${fmt(m[0])}</b><em>${m[2]}</em></div>`).join('')}</div>
 <div class="dashboard-grid"><section class="panel"><div class="panel-top"><div><h2>${t('标段总览','Segment overview')}</h2><p>${t('只突出设计总量、到货率、剩余率和备品；不同单位分别计算百分比。','Show design total, received rate, remaining rate and spares; percentages are calculated separately by unit.')}</p></div><button class="quiet" data-page="inventory">${t('打开仓库明细','Open warehouse detail')}</button></div>${contractRows.length?table([t('标段','Segment'),t('物资明细','Item lines'),t('设计总量','Design total'),t('到货率','Received %'),t('剩余率','Remaining %'),t('备品','Spares'),t('最近入库','Latest receipt'),t('操作','Action')],contractRows.map(g=>`<tr><td><span class="name">${esc(segmentLabel(g.code))}</span></td><td>${g.items.length}</td><td class="name">${qtySummary(g,'current')}</td><td>${pctSummary(g,'received')}</td><td>${pctSummary(g,'outstanding')}</td><td>${qtySummary(g,'spare')}</td><td>${dateText(g.inbound_last)}</td><td><button class="quiet small" data-contract="${esc(g.code)}">${t('查看标段','Open segment')}</button></td></tr>`)):empty(t('还没有标段库存','No segment stock yet'),t('从入库办理上传第一批到货清单。','Upload the first arrival list from Receipts.'))}${unmappedRows.length?`<div class="warning-list">${t('发现未映射的历史标段记录，请核对后再纳入A1-A16。','Unmapped historical segment records were found. Review them before assigning A1-A16.') } ${unmappedRows.map(g=>`${esc(g.code)}（${g.items.length} ${t('项','items')}）`).join('；')}</div>`:''}</section>
 <section class="panel"><div class="panel-top"><div><h2>${t('需要关注','Needs attention')}</h2><p>${t('这里仅提示，不会自动修改库存。','Alerts only; nothing is changed automatically.')}</p></div></div>${held.length?`<div class="warning-list">${t(`有 ${held.length} 条库存处于待检或隔离，普通出库已限制。`,` ${held.length} stock lines are pending inspection or quarantined; normal issue is blocked.`)}</div>`:`<div class="success-box">${t('当前没有待检或隔离库存。','No pending or quarantined stock.')}</div>`}<div class="actions"><button class="quiet" data-page="inbound">${t('办理入库','Create receipt')}</button><button class="quiet" data-page="outbound">${t('办理出库','Create issue')}</button><button class="quiet" data-page="ledger">${t('查看流水总账','Open transaction ledger')}</button></div></section></div>
 <section class="panel"><div class="panel-top"><div><h2>${t('最近业务单据','Recent documents')}</h2><p>${t('入库和出库均由系统生成单据，补打不会重复计算。','Receipts and issues are system-generated; reprints never repost quantities.')}</p></div><button class="quiet" data-page="documents">${t('全部单据','All documents')}</button></div>${recent.length?table([t('单号 / 时间','Number / Time'),t('类型','Type'),t('业务单号','Reference'),t('经办人','Operator'),t('状态','Status')],recent.map(d=>`<tr><td><span class="code">${esc(d.number)}</span><div class="sub">${esc(d.created)}</div></td><td>${badge(d.kind)}</td><td>${esc(d.external_ref)||'—'}</td><td>${esc(d.operator)}</td><td>${d.reversed_by?t('已冲销','Reversed'):t('已确认','Posted')}</td></tr>`)):empty(t('暂无业务单据','No documents yet'),t('确认入库或出库后会出现在这里。','Confirmed receipts and issues will appear here.'))}</section>
 ${reconciliationPanel()}
 <section class="panel"><div class="panel-top"><div><h2>${t('备品单独查看','Spares are separate')}</h2><p>${t('备品不并入主物资设计量和主库存统计。','Spares are kept separate from main design quantity and stock.')}</p></div><button class="quiet" data-page="spares">${t('打开备品情况','Open spares')}</button></div></section>`;
}

function ledgerPage(){
 const rows=db.ledger||[];
 return `<p class="intro">${t('流水总账记录每一笔入库、出库和更正，用于追溯；库存总量由这些流水自动计算。','The transaction ledger records every receipt, issue and correction for traceability; stock is calculated from these movements.')}</p>${reconciliationPanel()}<section class="panel"><div class="panel-top"><div><h2>${t('流水总账','Transaction ledger')}</h2><p>${t('可按单据、物资、标段、批次或库位查找。点击单据号可查看完整单据。','Search by document, item, segment, batch or bin. Click a document number to open the full document.')}</p></div><div class="actions"><input id="ledger-search" class="search" placeholder="${t('搜索单号、物资、标段、批次、箱号、库位','Search number, item, segment, batch, box or bin')}"><select id="ledger-kind"><option value="">${t('全部类型','All types')}</option><option value="IN">${t('只看入库','Receipts only')}</option><option value="OUT">${t('只看出库','Issues only')}</option><option value="HANDOVER">${t('只看备品移交','Spares handover only')}</option><option value="MOVE">${t('只看移库','Bin transfers only')}</option><option value="STATE">${t('只看状态调整','Status changes only')}</option><option value="REV">${t('只看更正','Corrections only')}</option></select></div></div>${rows.length?table([t('时间','Date'),t('单据号','Document'),t('类型','Type'),t('物资','Item'),t('数量变化','Change'),t('标段 / 批次 / 箱号','Segment / Batch / Box'),t('仓库 / 库位','Warehouse / Bin'),t('经办人','Operator')],rows.map(r=>`<tr data-ledger-kind="${esc(r.kind)}" data-search="${esc(Object.values(r).join(' ').toLowerCase())}"><td>${dateText(r.date)}</td><td><button class="quiet small" data-doc="${r.doc_id}">${esc(r.number)}</button></td><td>${badge(r.kind)}</td><td><span class="name">${esc(r.name)}</span><div class="sub">${esc(r.code)}${r.spec?' · '+esc(r.spec):''}</div></td><td class="${r.delta<0?'warning':'name'}">${r.delta>0?'+':''}${fmt(r.delta)} ${esc(r.unit)}</td><td>${esc(segmentLabel(r.package))}<div class="sub">${esc(r.batch)} · ${esc(r.box)||'—'}</div></td><td>${esc(r.warehouse)} / <b>${esc(r.bin)}</b></td><td>${esc(r.operator)}</td></tr>`)) : empty(t('暂无流水','No transactions yet'),t('确认入库或出库后会自动生成。','Transactions appear after a receipt or issue is confirmed.'))}</section>`;
}

function sparesPage(){
 const rows=(db.stock||[]).filter(s=>s.state==='SPARE');
 return `<p class="intro">${t('备品单独管理和单独存放，不计入主物资库存和设计量。','Spares are managed and stored separately from main stock and design quantity.')}</p><div class="metrics"><div class="metric"><small>${t('备品库存明细','Spare stock lines')}</small><b>${fmt(rows.length)}</b><em>${t('仅显示预留备品状态','Reserved spares only')}</em></div><div class="metric"><small>${t('备品数量','Spare quantity')}</small><b>${unitTotals(rows)}</b><em>${t('按单位分别统计','Grouped by unit')}</em></div><div class="metric"><small>${t('备品移交单','Spares handovers')}</small><b>${fmt(db.documents.filter(d=>d.kind==='HANDOVER'&&!d.reversed_by).length)}</b><em>${t('独立单据','Separate documents')}</em></div></div><section class="panel"><div class="panel-top"><div><h2>${t('备品明细','Spare detail')}</h2></div><button class="quiet" data-page="outbound">${t('办理备品移交','Handover spares')}</button></div>${rows.length?table([t('物资','Item'),t('批次 / 箱号','Batch / Box'),t('仓库 / 库位','Warehouse / Bin'),t('数量','Quantity'),t('属性','Attribute')],rows.map(s=>`<tr><td><span class="name">${esc(s.name)}</span><div class="sub">${esc(s.code)}${s.spec?' · '+esc(s.spec):''}</div></td><td>${esc(s.batch)} / ${esc(s.box)||'—'}</td><td>${esc(s.warehouse)} / <b>${esc(s.bin)}</b></td><td>${fmt(s.qty)} ${esc(s.unit)}</td><td>${esc(s.attribute)||'—'}</td></tr>`)):empty(t('暂未登记备品','No spares registered'),t('备品确认入库后会单独出现在这里。','Confirmed spare receipts appear here separately.'))}</section>`;
}
function contractPage(code){const g=(db.contracts||[]).find(x=>x.code===code);if(!g){selectedContract='';return overview();}const stock=db.stock.filter(s=>s.package===g.code);return `<p class="intro"><button class="quiet small" data-contract-back="1">← ${t('返回标段列表','Back to segments')}</button></p><div class="panel"><div class="panel-top"><div><div class="eyebrow">SEGMENT</div><h2>${esc(segmentLabel(g.code))}</h2><p>${t('该标段的设备、数量、库存位置和收发日期','Equipment, quantities, stock positions and transaction dates for this segment')}</p></div><span class="tag">${t('单独库存页','Segment inventory')}</span></div><div class="metrics"><div class="metric"><small>${t('标段数量','Segment qty')}</small><b>${qtySummary(g,'current')}</b></div><div class="metric"><small>${t('累计入库','Received')}</small><b>${qtySummary(g,'received')}</b></div><div class="metric"><small>${t('累计出库','Issued')}</small><b>${qtySummary(g,'issued')}</b></div><div class="metric"><small>${t('当前库存','On hand')}</small><b>${qtySummary(g,'onhand')}</b></div></div>${table([t('设备编码 / 名称','Equipment code / name'),t('规格 / 单位','Specification / Unit'),t('标段数量','Segment qty'),t('入库数量','Received'),t('出库数量','Issued'),t('当前库存','On hand'),t('入库日期','Receipt dates'),t('出库日期','Issue dates')],g.items.map(r=>`<tr><td><span class="code">${esc(r.code)}</span><br><span class="name">${esc(r.name)}</span></td><td>${esc(r.spec)||'—'} / ${esc(r.unit)}${r.attribute?' · '+esc(r.attribute):''}</td><td>${r.current===null?'—':fmt(r.current)}</td><td>${fmt(r.received)}</td><td>${fmt(r.issued)}</td><td class="name">${fmt(r.onhand)}</td><td>${dateRange(r.inbound_first,r.inbound_last)}</td><td>${dateRange(r.outbound_first,r.outbound_last)}</td></tr>`))}</div><section class="panel"><div class="panel-top"><h2>${t('该标段库存位置','Stock positions in this segment')}</h2><button class="quiet" data-page="outbound">${t('办理出库','Issue stock')}</button></div>${stock.length?table([t('设备','Equipment'),t('到货批次','Arrival batch'),t('箱号','Box no.'),t('仓库 / 库位','Warehouse / Bin'),t('状态','Status'),t('数量','Quantity')],stock.map(s=>`<tr><td><span class="code">${esc(s.code)}</span><br>${esc(s.name)}</td><td>${esc(s.batch)}</td><td>${esc(s.box)||'—'}</td><td>${esc(s.warehouse)} / <b>${esc(s.bin)}</b></td><td>${badge(s.state)}</td><td>${stockBalanceText(s)}</td></tr>`)):empty(t('该标段暂无在库数量','No on-hand stock for this segment'),t('入库确认后，位置和数量会在这里显示。','Confirmed receipts will appear here with locations and quantities.'))}</section>`;}
function materialsOverview(){
 if(selectedContract)return contractPage(selectedContract);
 return `<p class="intro">${t('按物资编码查看设计数量、累计入库、出库和当前结余。','Review design quantities, receipts, issues and balances by item code.')}</p>
 <div class="metrics">${[[db.items.length,'物资种类','Item types','按物资编码区分','By item code'],[db.items.filter(r=>Number(r.onhand||0)>0).length,'当前有库存物资','Items in stock','至少有一条在库记录','At least one stock position'],[db.items.filter(r=>Number(r.outstanding||0)>0).length,'未到货物资','Outstanding items','按设计量与入库量比较','Compared with receipts'],[db.changes.length,'设计变更记录','Design changes','不改变实物库存','Do not change physical stock']].map(m=>`<div class="metric"><small>${t(m[1],m[2])}</small><b>${fmt(m[0])}</b><em>${t(m[3],m[4])}</em></div>`).join('')}</div>
 <section class="panel"><div class="panel-top"><div><h2>${t('物资明细','Item detail')}</h2><p>${t('这是物资层入口；要查箱子和箱内件，请进入“库存总览”。','This is the item-level entry. Open Inventory for boxes and contents.')}</p></div><div class="actions"><input class="search" id="search" placeholder="${t('搜索名称、编码、标段、规格','Search name, code, lot or specification')}"><a class="quiet" href="/api/export">${t('导出物资','Export items')}</a></div></div>
 ${db.items.length?table([t('物资 / 规格','Item / Specification'),t('标段','Segment'),t('单位','Unit'),t('设计 / 变更','Baseline / Change'),t('现行需求','Requirement'),t('累计入库','Received'),t('累计出库','Issued'),t('已移交','Handed over'),t('在库','On hand'),t('未到货','Outstanding')],db.items.map(r=>`<tr data-search="${esc(Object.values(r).join(' ').toLowerCase())}"><td><span class="code">${esc(r.code)}</span><br><span class="name">${esc(r.name)}</span><div class="sub">${esc(r.spec)}</div></td><td>${esc(segmentLabel(r.package))}</td><td>${esc(r.unit)}</td><td>${fmt(r.baseline)} / ${fmt(r.change)}</td><td>${fmt(r.current)}</td><td>${fmt(r.received)}</td><td>${fmt(r.issued)}</td><td>${fmt(r.handed)}</td><td class="name">${fmt(r.onhand)}</td><td>${fmt(r.outstanding)}</td></tr>`)):empty(t('从第一批物资开始','Start with your first receipt'),t('打开 Excel 入库，上传物资清单；也可以先导入设计总量。','Open Excel receipt to upload a list, or import the design baseline first.'))}</section>`;
}
function overview(){
 if(selectedContract)return contractPage(selectedContract);
 const pending=db.stock.filter(s=>s.state==='PENDING'||s.state==='QUARANTINE').length;
 return `<p class="intro">${t('从设计需求到库存位置，查看每一种物资的当前情况。','Review requirements, receipts, issues and exact storage positions.')}</p>
 <div class="metrics">${[[db.items.length,'物资种类','Item types','按编码区分','By item code'],[db.stock.length,'有库存的货位明细','Stock positions','批次 / 库位 / 状态','Batch / bin / status'],[pending,'待检或隔离明细','Held positions','普通出库已限制','Blocked from normal issue'],[db.documents.filter(d=>d.kind==='OUT'&&!d.reversed_by).length,'有效出库单','Active issue notes','补打不重复扣库','Reprints do not deduct stock']].map(m=>`<div class="metric"><small>${t(m[1],m[2])}</small><b>${fmt(m[0])}</b><em>${t(m[3],m[4])}</em></div>`).join('')}</div>
 ${contractIndex()}
 <details class="secondary-view"><summary>${t('辅助明细：平面台账与库位表','Supporting detail: flat ledger and locations')}</summary>
 <section class="panel"><div class="panel-top"><div><h2>${t('物资台账','Materials ledger')}</h2><p>${t('数量按各自单位显示；厂家明细按固定标段关联。','Quantities retain their own units. Supplier details link through the fixed segments.')}</p></div><div class="actions"><input class="search" id="search" placeholder="${t('搜索名称、编码、标段','Search name, code or segment')}"><a class="quiet" href="/api/export">${t('导出库存','Export stock')}</a></div></div>
 ${db.items.length?table([t('物资 / 规格','Item / Specification'),t('标段','Segment'),t('单位','Unit'),t('设计 / 变更','Baseline / Change'),t('现行需求','Requirement'),t('累计入库','Received'),t('累计领用','Issued'),t('已移交','Handed over'),t('在库','On hand'),t('未到货','Outstanding')],db.items.map(r=>`<tr data-search="${esc(Object.values(r).join(' ').toLowerCase())}"><td><span class="code">${esc(r.code)}</span><br><span class="name">${esc(r.name)}</span><div class="sub">${esc(r.spec)}</div></td><td>${esc(segmentLabel(r.package))}</td><td>${esc(r.unit)}</td><td>${fmt(r.baseline)} / ${fmt(r.change)}</td><td>${fmt(r.current)}</td><td>${fmt(r.received)}</td><td>${fmt(r.issued)}</td><td>${fmt(r.handed)}</td><td class="name">${fmt(r.onhand)}</td><td>${fmt(r.outstanding)}</td></tr>`)):empty(t('从第一批物资开始','Start with your first receipt'),t('打开 Excel 入库，上传物资清单；也可以先导入设计总量。','Open Excel receipt to upload a list, or import the design baseline first.'))}</section>
 <section class="panel"><div class="panel-top"><h2>${t('库存位置','Stock locations')}</h2><button class="quiet" data-page="outbound">${t('办理出库 / 移库','Issue / transfer')}</button></div>${stockTable()}</section></details>
 <section class="panel"><details><summary>${t('发运批次及状态','Shipment batches and status')}</summary><p class="helper">${t('物流状态手动选择并留痕；不会改变库存数量。到货批次使用B01、B02等简短编号。','Transport status changes are logged and do not alter stock quantities. Use short arrival batch codes such as B01 and B02.')}</p><div class="form-grid">${input('batch-code',t('到货批次号 *','Arrival batch *'))}${input('batch-supplier',t('厂家','Supplier'))}<label>${t('物流状态','Transport status')}<select id="batch-status">${options(['PLANNED','DISPATCHED','SEA','CUSTOMS','RELEASED','ROAD','ARRIVED'])}</select></label>${input('batch-operator',t('经办人 *','Operator *'),sessionStorage.getItem('operator')||'')}${input('batch-note',t('备注 / 依据','Note / Reference'))}</div><button data-action="batch-save">${t('保存批次状态','Save batch status')}</button>${db.batches.length?table([t('合同批次','Contract batch'),t('厂家','Supplier'),t('状态','Status'),t('更新时间','Updated')],db.batches.map(b=>`<tr><td>${esc(b.code)}</td><td>${esc(b.supplier)}</td><td>${badge(b.status)}</td><td>${esc(b.updated)}</td></tr>`)):''}<details><summary>${t('状态记录','Status history')}</summary>${table([t('批次','Batch'),t('原状态','Previous'),t('新状态','New'),t('经办人','Operator'),t('备注','Note')],db.events.map(e=>`<tr><td>${esc(e.batch)}</td><td>${esc(label(e.old_status||'—'))}</td><td>${esc(label(e.new_status))}</td><td>${esc(e.operator)}</td><td>${esc(e.note)}</td></tr>`))}</details></details></section>
 <section class="panel"><details><summary>${t('设计基准与变更','Design baseline and changes')}</summary><p class="helper">${t('设计量首次导入后锁定；变更单独记录，不修改实际库存。','The first baseline is locked. Changes are recorded separately and never alter physical stock.')}</p><button class="quiet" data-action="baseline">${t('导入设计总量','Import baseline')}</button><div class="form-grid">${input('change-code',t('物资编码 *','Item code *'))}${input('change-qty',t('变更量（增加为正，减少为负）','Change (+ increase / − decrease)'),'', 'number','step="0.000001"')}${input('change-operator',t('经办人 *','Operator *'),sessionStorage.getItem('operator')||'')}${input('change-reason',t('变更依据及原因 *','Change reference and reason *'))}</div><button data-action="change-save">${t('记录设计变更','Record design change')}</button>${table([t('编码','Code'),t('变更量','Change'),t('依据','Reference'),t('经办人','Operator')],db.changes.map(c=>`<tr><td>${esc(c.code)}</td><td>${fmt(c.delta/1000000)}</td><td>${esc(c.reason)}</td><td>${esc(c.operator)}</td></tr>`))}</details></section>`;
}
function stockTable(){return db.stock.length?table([t('物资 / 标段','Item / Segment'),t('到货批次','Arrival batch'),t('箱号','Box no.'),t('仓库 / 库位','Warehouse / Bin'),t('状态','Status'),t('数量','Quantity')],db.stock.map(s=>`<tr data-search="${esc(Object.values(s).join(' ').toLowerCase())}"><td><span class="code">${esc(s.code)}</span><br>${esc(s.name)}<div class="sub">${esc(segmentLabel(s.package))}${s.attribute?' · '+esc(s.attribute):''}</div></td><td>${esc(s.batch)}</td><td>${esc(s.box)||'—'}</td><td>${esc(s.warehouse)} / <b>${esc(s.bin)}</b></td><td>${badge(s.state)}</td><td>${stockBalanceText(s)}</td></tr>`)):empty(t('暂无库存','No stock yet'),t('确认入库后，这里显示具体位置及数量。','Confirmed receipts appear here with quantities and locations.'));}
function inbound(){return `<p class="intro">${importKind==='BASELINE'?t('首次确认合同/设计数量；不会增加库存。','Confirm the contract/design baseline once; stock is unchanged.'):t('上传清单，核对一次，系统生成单据并更新库存。','Upload a list, verify it, then post a receipt and update stock.')}</p><section class="panel"><div class="panel-top"><div><div class="step-label">01 / ${t('选择业务与文件','FILE AND TRANSACTION')}</div><h2>${importKind==='BASELINE'?t('导入设计总量','Import design baseline'):t('Excel 批量导入','Excel batch import')}</h2></div><a class="quiet" href="/api/template">${t('下载填写示例 CSV','Download sample CSV')}</a></div>
 <div class="success-box">${importKind==='BASELINE'?t('设计总量只录入一次并锁定；后续变化使用设计变更记录。','The design baseline is entered once and locked; later changes use a separate change record.'):t('当前流程只处理到货入库。资料归档和文件夹管理暂不加入本版。','This version handles arrival receipts only. Document archiving and folder automation are not included.')}</div>
 <div class="upload-box"><strong>${t('上传 .xlsx 或 .csv','Upload .xlsx or .csv')}</strong><p>${t('系统按固定规则自动识别表头。最多12MB、10000条；公式请先转为值。一个箱子可以只填写一次箱号并合并单元格，系统会自动带到下面的箱内明细。','Headers are recognized automatically using the fixed rules. Up to 12 MB / 10000 rows. Convert formulas to values first. Enter a box number once and merge it across its detail rows; the system carries it down automatically.')}</p><input type="file" id="file" accept=".xlsx,.csv"><div id="filename" class="helper">${esc(upload?.filename||'')}</div></div>
 <div class="form-grid">${input('ref',t('业务单号（可留空自动生成）','Business reference (optional; auto-generated if blank)'),upload?.ref||'')}${input('operator',t('经办人 *','Operator *'),sessionStorage.getItem('operator')||'')}${input('party',t('厂家 / 供货单位','Supplier'))}<label>${t('标段 *','Segment *')}<select id="default-package" required>${segmentOptions(selectedSegment||upload?.segment||'')}</select></label>${input('default-batch',t('到货批次（自动生成）','Arrival batch (generated)'))}${input('default-warehouse',t('入库仓库','Receipt warehouse'),'主仓库')}${input('default-bin',t('入库库位','Receipt bin'),'待分配')}<label>${t('库存状态','Stock status')}<select id="default-state">${options(['AVAILABLE','PENDING','QUARANTINE','SPARE'],'AVAILABLE')}</select></label>${input('header',t('表头所在行（0=自动识别）','Header row (0 = auto detect)'),0,'number','min="0" max="100"')}<label>${t('工作表','Worksheet')}<select id="sheet">${preview?preview.sheets.map(s=>`<option ${s===preview.sheet?'selected':''}>${esc(s)}</option>`).join(''):`<option value="">${t('自动选择首张表','First worksheet')}</option>`}</select></label></div>
 <button data-action="inspect">${t('识别文件','Read file')}</button><span class="helper"> ${t('仅预览，尚不入账','Preview only; no stock change')}</span></section><section id="preview"></section>`;}
function payload(){selectedSegment=$('default-package')?.value||selectedSegment;if(upload){upload.batchDate=$('batch-date')?.value||'';upload.batchNumber=$('batch-number')?.value.trim()||'1';upload.segment=selectedSegment;}return {...upload,kind:importKind,segment_required:true,arrival_date:$('batch-date')?.value||'',header:$('header').value,sheet:$('sheet').value,external_ref:$('ref').value,operator:$('operator').value,party:$('party').value,defaults:{package:selectedSegment,batch:composeBatch(),box:$('default-box')?.value||'',warehouse:$('default-warehouse').value,bin:$('default-bin').value,state:$('default-state').value}};}
function renderPreview(){const r=preview;$('preview').innerHTML=`<div class="panel"><div class="step-label">02 / ${t('自动识别并核对','AUTO-READ AND VERIFY')}</div><h2>${t('识别结果','Import preview')} · ${r.count} ${t('行','rows')}</h2>${r.errors.length?`<div class="error-list">${r.errors.map(esc).join('\n')}</div>`:`<div class="success-box">${t('自动识别通过。确认后生成单据并一次性入账。','Automatic recognition passed. Confirm to post the document and ledger once.')}</div>`}${r.warnings?.length?`<div class="warning-list">${r.warnings.map(esc).join('\n')}</div>`:''}
 ${table([t('源行','Row'),...['code','name','spec','unit','qty','batch','box','warehouse','bin','package','state','attribute'].map(k=>t(...fields[k]))],r.rows.slice(0,100).map(x=>`<tr><td>${x.source_row}</td>${['code','name','spec','unit','qty','batch','box','warehouse','bin','package'].map(k=>`<td>${esc(x[k])}</td>`).join('')}<td>${badge(x.state)}</td><td>${esc(x.attribute)}</td></tr>`))}<p class="helper">${t('系统已按固定规则自动匹配表头；显示前100行，全部明细参与校验。原始文件随单据保留。同箱号的多行会按物资、批次、仓库和库位合计，不同箱号分别保留。','Headers are matched automatically using the fixed rules. The first 100 rows are shown; all rows are validated and the original file is retained. Repeated items in the same box are totaled by item, batch, warehouse and bin; different box numbers remain separate.')}</p><button data-action="import-confirm" ${r.errors.length?'disabled':''}>${importKind==='IN'?t('确认入库并生成入库单','Confirm receipt'):t('确认锁定设计总量','Confirm baseline')}</button></div>`;}
function eligible(){return db.stock.filter(s=>action==='OUT'?s.state==='AVAILABLE':action==='HANDOVER'?s.state==='SPARE':true);}
function issueGroups(){
 const groups=new Map();
 eligible().forEach(s=>{
   const key=[s.code,s.name,s.spec,s.unit,s.package,s.attribute].map(v=>v||'').join('\u001f');
   if(!groups.has(key))groups.set(key,{key,code:s.code,name:s.name,spec:s.spec,unit:s.unit,package:s.package,attribute:s.attribute,rows:[],available:0});
   const g=groups.get(key);g.rows.push(s);g.available+=Number(s.qty||0);
 });
 return [...groups.values()].sort((a,b)=>`${a.package||''}${a.code||''}${a.name||''}`.localeCompare(`${b.package||''}${b.code||''}${b.name||''}`,'zh-CN'));
}
function applyBulkFilters(){
 const q=($('out-search')?.value||'').trim().toLowerCase(), pack=$('out-contract')?.value||'';
 document.querySelectorAll('[data-out-group]').forEach(row=>{const hay=(row.dataset.search||'').toLowerCase();row.hidden=!!((q&&!hay.includes(q))||(pack&&row.dataset.package!==pack));});
 const state=$('bulk-issue-state'), visible=[...document.querySelectorAll('[data-out-group]')].filter(row=>!row.hidden).length;
 if(state&&visible>1)state.textContent=t(`当前筛选匹配 ${visible} 项，请按物资编码、规格和属性确认；不同编码不会合并。`,`This filter matches ${visible} items. Confirm the item code, specification and attribute; different codes are never merged.`);
 if(state&&visible===1)state.textContent=t('当前筛选只匹配1项，可直接填写本次数量。','This filter matches one item. Enter the issue quantity directly.');
}
function bulkIssueHTML(){
 const groups=issueGroups(), packages=[...new Set(groups.map(g=>g.package).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN'));
 if(!groups.length)return empty(t('没有可出库的可用库存','No available stock to issue'),t('待检、隔离和已出库库存不会出现在普通出库列表中。','Pending, quarantined and already issued stock are excluded from normal issues.'));
 const rows=groups.map((g,i)=>`<tr data-out-group="${i}" data-package="${esc(g.package||'')}" data-search="${esc([g.code,g.name,g.spec,g.package,g.attribute].filter(Boolean).join(' '))}"><td><input type="checkbox" data-group-check="${i}" aria-label="${t('选择','Select')} ${esc(g.name||g.code)}"></td><td><span class="code">${esc(g.code)}</span><br><span class="name">${esc(g.name)}</span>${g.spec?`<div class="sub">${esc(g.spec)}</div>`:''}${g.attribute?`<div class="sub">${esc(g.attribute)}</div>`:''}</td><td>${esc(segmentLabel(g.package))}</td><td>${fmt(g.available)} ${esc(g.unit)}</td><td>${g.rows.length} ${t('个库位','locations')}</td><td><input type="number" min="0" max="${esc(g.available)}" step="0.000001" data-group-qty="${i}" placeholder="0" aria-label="${t('本次数量','Issue quantity')} ${i+1}"></td></tr>`);
 return `<div class="bulk-toolbar"><input id="out-search" class="search" placeholder="${t('搜索物资、编码、规格','Search item, code or specification')}"><select id="out-contract"><option value="">${t('全部标段','All segments')}</option>${packages.map(v=>`<option value="${esc(v)}">${esc(segmentLabel(v))}</option>`).join('')}</select><button class="quiet small" data-out-bulk="all">${t('全选可见','Select visible')}</button><button class="quiet small" data-out-bulk="clear">${t('清空选择','Clear')}</button></div>${table([t('选择','Select'),t('物资','Material'),t('标段','Segment'),t('可用总量','Available total'),t('库位数','Locations'),t('本次数量','Issue qty')],rows)}`;
}
function addSelectedGroups(){
 const groups=issueGroups(), selected=[...document.querySelectorAll('[data-group-check]')].filter(cb=>cb.checked||Number(document.querySelector(`[data-group-qty="${cb.dataset.groupCheck}"]`)?.value||0)>0);
 if(!selected.length)throw Error(t('请先勾选要出库的物资','Select at least one material first'));
 selected.forEach(cb=>{
   const i=Number(cb.dataset.groupCheck), g=groups[i], qty=Number(document.querySelector(`[data-group-qty="${i}"]`)?.value||0);
   if(!(qty>0))throw Error(t(`请输入 ${g.name||g.code} 的本次数量`,`Enter an issue quantity for ${g.name||g.code}`));
   if(qty>g.available+1e-9)throw Error(t(`${g.name||g.code} 出库量超过可用总量`,`Issue quantity exceeds available total for ${g.name||g.code}`));
   const ids=new Set(g.rows.map(s=>s.id));cart=cart.filter(r=>!ids.has(r.stock_id));
   let remaining=qty;g.rows.slice().sort((a,b)=>a.id-b.id).forEach(s=>{if(remaining<=1e-9)return;const part=Math.min(Number(s.qty||0),remaining);if(part>0){cart.push({stock_id:s.id,qty:part});remaining-=part;}});
 });
}
function syncBulkCart(){
 const groups=issueGroups(), next=[];let invalid=false, included=0;
 groups.forEach((g,i)=>{
   const field=document.querySelector(`[data-group-qty="${i}"]`), check=document.querySelector(`[data-group-check="${i}"]`), qty=Number(field?.value||0), selected=!!(check?.checked||qty>0);
   field?.classList.toggle('invalid',selected&&(!(qty>0)||qty>g.available+1e-9));
   if(!selected)return;
   if(!(qty>0)||qty>g.available+1e-9){invalid=true;return;}
   included++;
   let remaining=qty;g.rows.slice().sort((a,b)=>a.id-b.id).forEach(s=>{if(remaining<=1e-9)return;const part=Math.min(Number(s.qty||0),remaining);if(part>0){next.push({stock_id:s.id,qty:part});remaining-=part;}});
 });
 cart=next;
 const cartEl=$('cart');if(cartEl)cartEl.innerHTML=cartHTML();
 const post=document.querySelector('[data-action="post"]');if(post)post.disabled=!cart.length||invalid;
 const state=$('bulk-issue-state');if(state){const visible=[...document.querySelectorAll('[data-out-group]')].filter(row=>!row.hidden).length, caution=visible>1?t(`当前筛选还有 ${visible} 项，请按编码/规格确认。`,`There are ${visible} matching items; confirm code/specification.`):'';state.textContent=invalid?t('有数量超过可用库存，请修改后再确认。', 'One or more quantities exceed available stock. Correct them before confirming.'):included?`${t(`${included} 项已自动加入待出库清单。`,`${included} item(s) are automatically added to the pending issue list.`)}${caution?` ${caution}`:''}`:(caution||t('填写数量后会自动加入待出库清单。','Enter a quantity to add it automatically to the pending issue list.'));state.className=invalid?'bulk-state invalid':'bulk-state';}
}
function outbound(){
 const bulk=action==='OUT';
 const picker=bulk?`<div class="bulk-issue"><div class="helper">${t('直接在“本次数量”填写数字，系统会自动加入待出库清单，并从多个批次和库位拆分。','Enter a number in “Issue qty” and it is added automatically; the system allocates across batches and locations.')}</div><div id="bulk-issue-list">${bulkIssueHTML()}</div><div id="bulk-issue-state" class="bulk-state">${t('填写数量后会自动加入待出库清单。','Enter a quantity to add it automatically to the pending issue list.')}</div></div>`:`<div class="actions"><label class="stock-pick" style="flex:1">${t('物资 / 标段 / 仓库 / 库位','Item / Segment / Warehouse / Bin')}<select id="stock-select"><option value="">${t('选择物资位置','Select stock position')}</option>${eligible().map(s=>`<option value="${s.id}">${esc(s.code)} · ${esc(s.name)}${s.package?' · '+esc(segmentLabel(s.package)):''} · ${esc(s.warehouse)}/${esc(s.bin)} · ${fmt(s.qty)} ${esc(s.unit)} · ${esc(label(s.state))}</option>`).join('')}</select></label><button class="quiet" data-action="add-cart">${t('添加到单据','Add to document')}</button></div>`;
 return `<p class="intro">${t('选择实际取货物资，录入数量，单据与库存同步完成。','Select materials and quantities. Posting updates both the document and stock.')}</p><section class="panel"><div class="panel-top"><h2>${t('办理库存业务','Stock transaction')}</h2><span class="tag">${t('确认才扣库存','Stock changes on confirmation')}</span></div><div class="switches">${['OUT','HANDOVER','MOVE','STATE'].map(k=>`<button class="quiet ${action===k?'selected':''}" data-stock-kind="${k}">${esc(label(k))}</button>`).join('')}</div><div class="form-grid">${input('out-operator',t('经办人 *','Operator *'),sessionStorage.getItem('operator')||'')}${input('out-party',t('领用 / 接收单位 *','Receiving party *'))}${input('out-purpose',t('用途 / 安装区域 / 原因 *','Purpose / Area / Reason *'))}${action==='MOVE'?input('out-warehouse',t('目标仓库 *','Destination warehouse *'))+input('out-bin',t('目标库位 *','Destination bin *')):''}${action==='STATE'?`<label>${t('调整后的状态','New stock status')}<select id="out-state">${options(['AVAILABLE','PENDING','QUARANTINE','SPARE'])}</select></label>`:''}</div>${picker}<div id="cart">${cartHTML()}</div><p class="helper">${t('出库单独编号；系统自动保留每一项的到货批次、箱号和库位来源。','Issue documents have their own number. The arrival batch, box and bin source of every line are retained automatically.')}</p><button data-action="post" ${cart.length?'':'disabled'}>${t('确认并生成出库单','Confirm and create issue document')}</button></section>`;
}
function cartHTML(){return cart.length?`<p class="helper split-preview-note">${t('系统建议的批次/库位拆分如下，可逐行调整；确认前不会扣库存。','The suggested batch/bin split is shown below. Adjust each line if needed; stock is unchanged until confirmation.')}</p>${table([t('物资 / 位置','Item / Location'),t('当前库存','On hand'),t('本次数量','Quantity'),t('操作','Action')],cart.map((r,i)=>{const s=db.stock.find(s=>s.id===r.stock_id);return `<tr class="cart"><td><span class="code">${esc(s?.code)}</span><br>${esc(s?.name)}<div class="sub">${esc(s?.warehouse)} / ${esc(s?.bin)} · ${t('到货批次','Arrival batch')} ${esc(s?.batch)} · ${t('箱号','Box')} ${esc(s?.box)||'—'}${s?.spec?' · '+esc(s.spec):''}${s?.attribute?' · '+esc(s.attribute):''}</div></td><td>${fmt(s?.qty)} ${esc(s?.unit)}</td><td><input aria-label="${t('数量','Quantity')} ${i+1}" data-cart="${i}" type="number" step="0.000001" min="0.000001" max="${s?.qty}" value="${esc(r.qty)}"></td><td><button class="quiet small" data-remove="${i}">${t('移除','Remove')}</button></td></tr>`;}))}`:empty(t('单据尚无物资','No items in this document'),t('从上方选择库位并添加。','Select a stock position above and add it.'));}
function documentActions(d){const eligible=!d.reversed_by&&!['BASELINE','REV'].includes(d.kind);return `<button class="quiet small" data-doc="${d.id}">${t('查看 / 打印','View / Print')}</button>${eligible?`<button class="quiet small" data-reverse="${d.id}">${t('作废 / 冲销','Void / reverse')}</button><button class="danger small" data-delete="${d.id}">${t('管理员删除（需密码）','Admin delete (password)')}</button>`:''}`;}
function syncDeleteSelection(){deleteSelected=[...document.querySelectorAll('[data-delete-doc]:checked')].map(x=>Number(x.dataset.deleteDoc));const count=$('delete-selected-count');if(count)count.textContent=t(`已选择 ${deleteSelected.length} 张单据`,` ${deleteSelected.length} document(s) selected`);const post=document.querySelector('[data-action="delete-post"]');if(post)post.disabled=!deleteSelected.length;}
function deletePage(){const eligible=(db?.documents||[]).filter(d=>!d.reversed_by&&!['BASELINE','REV'].includes(d.kind));const selected=new Set(deleteSelected.map(Number));return `<p class="intro">${t('删除办理用于整张误录单据。先筛选并勾选，再输入管理员密码一次提交；库存会自动回滚。','Use Admin deletion for whole mistaken documents. Filter and select documents, then enter the administrator password once; stock is rolled back automatically.')}</p><section class="panel"><div class="panel-top"><div><h2>${t('管理员删除办理','Admin deletion')}</h2><p class="helper">${db?.admin_password_configured?t('已设置管理员密码。被后续流水使用的单据不能删除，请改用作废/冲销。','An administrator password is set. Documents with later stock movements cannot be deleted; use void/reversal.') :t('管理员密码尚未设置，请先到“单据查询”设置。','Set the administrator password first from Documents.')}</p></div><button class="quiet small" data-page="documents">${t('去单据查询设置密码','Open Documents to set password')}</button></div><div class="form-grid">${input('delete-operator',t('管理员姓名 *','Administrator *'),sessionStorage.getItem('operator')||'')}${input('delete-password',t('管理员密码 *','Administrator password *'),'','password')}${input('delete-purpose',t('删除原因 *','Deletion reason'))}</div><div class="actions"><input id="delete-search" class="search" placeholder="${t('搜索单号、业务号、经办人','Search number, reference or operator')}"><button class="quiet small" data-delete-bulk="all">${t('全选当前结果','Select all results')}</button><button class="quiet small" data-delete-bulk="clear">${t('清空选择','Clear selection')}</button><span class="helper" id="delete-selected-count">${t(`已选择 ${selected.size} 张单据`,` ${selected.size} document(s) selected`)}</span></div>${eligible.length?table([t('选择','Select'),t('单号 / 时间','Number / Time'),t('类型','Type'),t('业务单号','Reference'),t('经办人','Operator'),t('状态','Status'),t('操作','Actions')],eligible.map(d=>`<tr data-delete-row="${d.id}" data-search="${esc(Object.values(d).join(' ').toLowerCase())}"><td><input type="checkbox" data-delete-doc="${d.id}" ${selected.has(Number(d.id))?'checked':''} aria-label="${t('选择','Select')} ${esc(d.number)}"></td><td><span class="name">${esc(d.number)}</span><div class="sub">${esc(d.created)}</div></td><td>${badge(d.kind)}</td><td>${esc(d.external_ref)}</td><td>${esc(d.operator)}</td><td>${t('可删除','Deletable')}</td><td><button class="quiet small" data-doc="${d.id}">${t('查看','View')}</button></td></tr>`)):empty(t('暂无可删除单据','No deletable documents'),t('设计基准单、冲销单和已冲销单不会出现在这里。','Baseline, reversal and already reversed documents are excluded.'))}<button class="danger" data-action="delete-post" ${selected.size?'':'disabled'}>${t('确认删除所选单据','Delete selected documents')}</button></section>`;}
function documents(){const configured=!!db?.admin_password_configured;return `<p class="intro">${t('入错的未确认预览直接取消；已确认单据可作废/冲销，整张误录单据可由管理员输入密码删除并回滚库存。','Cancel an unconfirmed preview. Void/reverse a posted document, or let an administrator delete a whole mistaken document with a password and roll back stock.')}</p><section class="panel"><div class="panel-top"><div><h2>${t('全部单据','All documents')}</h2><p class="helper">${configured?t('管理员删除已启用；修改密码需输入旧密码。','Admin deletion is enabled; changing the password requires the old password.'):t('首次使用管理员删除前，请先设置管理员密码。','Set an administrator password before the first deletion.')}</p></div><div class="actions"><input id="search" class="search" placeholder="${t('搜索单号、单位、经办人','Search number, party, operator')}"><a class="quiet small" href="/api/backup">${t('备份数据（含数据库与原件）','Backup (DB + sources)')}</a><button class="quiet small" data-action="admin-password">${configured?t('修改管理员密码','Change admin password'):t('设置管理员密码','Set admin password')}</button></div></div>${db.documents.length?table([t('单号 / 时间','Number / Time'),t('类型','Type'),t('业务单号','Reference'),t('单位','Party'),t('经办人','Operator'),t('状态','Status'),t('操作','Actions')],db.documents.map(d=>`<tr data-search="${esc(Object.values(d).join(' ').toLowerCase())}"><td><span class="name">${esc(d.number)}</span><div class="sub">${esc(d.created)}</div></td><td>${badge(d.kind)}</td><td>${esc(d.external_ref)}</td><td>${esc(d.party)||'—'}</td><td>${esc(d.operator)}</td><td>${d.reversed_by?t('已冲销','Reversed'):t('已确认','Posted')}</td><td><div class="actions">${documentActions(d)}</div></td></tr>`)):empty(t('暂无业务单据','No documents yet'),t('确认入库或出库后自动生成。','Documents are generated when a transaction is confirmed.'))}</section>`;}
async function showDoc(id){const d=await api('/api/document?id='+id);const batchTitle=d.kind==='IN'||d.kind==='BASELINE'?t('到货批次','Arrival batch'):t('来源到货批次','Arrival source');$('modal-body').innerHTML=`<div class="doc-head"><div><div class="eyebrow">SMART WAREHOUSE / MATERIALS</div><h2 class="doc-title">${esc(label(d.kind))}</h2><div class="sub">${t('系统生成 · 补打不重复入账','System generated · Reprints do not repost')}</div></div><div class="code">${esc(d.number)}<br>${esc(d.created)}<br>${d.reversed_by?t('已冲销','REVERSED'):t('已确认','POSTED')}</div></div><div class="doc-meta"><div>${t('业务编号','Reference')}: ${esc(d.external_ref)}</div><div>${t('经办人','Operator')}: ${esc(d.operator)}</div><div>${t('领用 / 供货单位','Receiving / Supplying party')}: ${esc(d.party)||'—'}</div><div>${t('用途 / 原因','Purpose / Reason')}: ${esc(d.purpose)||'—'}</div>${d.reverse_of?`<div>${t('冲销原单ID','Reversed document ID')}: ${d.reverse_of}</div>`:''}</div>${table([t('序号','No.'),t('编码 / 名称','Code / Item'),t('规格','Spec'),batchTitle,t('仓库 / 库位','Warehouse / Bin'),t('状态','Status'),t('数量','Qty'),t('单位','Unit')],d.lines.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.code)}<br>${esc(r.name)}</td><td>${esc(r.spec)}</td><td>${esc(r.batch)}</td><td>${esc(r.warehouse)} / ${esc(r.bin)}</td><td>${esc(label(r.state))}</td><td>${fmt(['OUT','HANDOVER'].includes(d.kind)?Math.abs(r.qty):r.qty)}</td><td>${esc(r.unit)}</td></tr>`))}<p class="helper">${t('不同单位不合并总数量。业务明细以系统保存记录为准。','Different units are not combined. The saved system record is authoritative.')}</p><div class="signatures"><span>${t('发料 / 交接人','Issued / Handed by')}: ${esc(d.operator)}</span><span>${t('接收签字','Received signature')}: ______________</span><span>${t('日期','Date')}: ______________</span></div><div class="doc-actions"><button data-action="print">${t('打印 / 保存为 PDF','Print / Save as PDF')}</button>${d.source_path?`<a class="quiet" href="/api/source?id=${d.id}">${t('下载原始清单','Download source')}</a>`:''}${!d.reversed_by&&!['BASELINE','REV'].includes(d.kind)?`<button class="quiet" data-reverse="${d.id}">${t('作废 / 冲销（保留流水）','Void / reverse (keep audit trail)')}</button><button class="danger" data-delete="${d.id}">${t('管理员删除（需密码）','Admin delete (password)')}</button>`:''}</div>`;$('modal').showModal();}
 const originalShowDoc=showDoc; showDoc=async function(id){await originalShowDoc(id);const d=await api('/api/document?id='+id);const meta=$('modal-body').querySelector('.doc-meta');if(meta&&d.arrival_date){const el=document.createElement('div');el.textContent=`${t('到货时间','Arrival time')}: ${dateText(d.arrival_date)}`;meta.append(el);}const tableEl=$('modal-body').querySelector('table');if(tableEl&&d.lines?.length){const h=tableEl.tHead?.rows[0];if(h){const th=document.createElement('th');th.textContent=t('箱号','Box no.');h.insertBefore(th,h.cells[4]||null);}d.lines.forEach((r,i)=>{const row=tableEl.tBodies?.[0]?.rows[i];if(!row)return;const cell=document.createElement('td');cell.textContent=r.box||'—';row.insertBefore(cell,row.cells[4]||null);if(r.attribute){row.cells[1].textContent+=` · ${r.attribute}`;}});}};
function simplifyPreview(){}
function mappedPayload(){return payload();}
function validateReceiptPackage(){
 const value=($('default-package')?.value||'').trim().toUpperCase();
 if(!value||!(db?.segments||[]).some(s=>s.code===value))throw Error(t('请选择固定标段 A1-A16','Select one fixed segment A1-A16'));
}
async function fileData(file){const buffer=new Uint8Array(await file.arrayBuffer());if(buffer.length>12*1024*1024)throw Error(t('文件超过12MB','File exceeds 12 MB'));let s='';for(let i=0;i<buffer.length;i+=32768)s+=String.fromCharCode(...buffer.subarray(i,i+32768));return {filename:file.name,content:btoa(s)};}
async function work(fn){if(posting)return;posting=true;document.body.setAttribute('aria-busy','true');try{await fn();}catch(e){notice(e.message,true);}finally{posting=false;document.body.removeAttribute('aria-busy');}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.page){page=b.dataset.page;draw();return;}
 if(b.dataset.treeToggle){document.querySelectorAll('#inventory-tree details').forEach(d=>d.open=b.dataset.treeToggle==='open');return;}
 if(b.dataset.contract){selectedContract=b.dataset.contract;page='inventory';draw();return;}
 if(b.dataset.contractBack){selectedContract='';page='inventory';draw();return;}
 if(b.dataset.kind){importKind=b.dataset.kind;preview=null;draw();return;}
 if(b.dataset.stockKind){action=b.dataset.stockKind;cart=[];draw();return;}
 if(b.dataset.outBulk==='all'){document.querySelectorAll('[data-out-group]:not([hidden]) [data-group-check]').forEach(x=>x.checked=true);return;}
 if(b.dataset.outBulk==='clear'){document.querySelectorAll('[data-group-check]').forEach(x=>x.checked=false);return;}
 if(b.dataset.deleteBulk==='all'){document.querySelectorAll('[data-delete-row]:not([hidden]) [data-delete-doc]').forEach(x=>x.checked=true);syncDeleteSelection();return;}
 if(b.dataset.deleteBulk==='clear'){document.querySelectorAll('[data-delete-doc]').forEach(x=>x.checked=false);syncDeleteSelection();return;}
 if(b.dataset.remove!==undefined){cart.splice(Number(b.dataset.remove),1);$('cart').innerHTML=cartHTML();document.querySelector('[data-action="post"]').disabled=!cart.length;return;}
 if(b.dataset.doc){work(()=>showDoc(b.dataset.doc));return;}
 if(b.dataset.delete){work(async()=>{if(!window.confirm(t('确认删除这张整单？系统会回滚库存，删除后只能从管理员操作记录追溯。','Delete this whole document? Stock will be rolled back; only the administrator action log will remain.')))return;const password=prompt(t('请输入管理员密码','Enter administrator password'));if(password===null)return;const reason=prompt(t('请输入删除原因','Enter deletion reason'));if(reason===null)return;const operator=prompt(t('管理员姓名','Administrator name'),sessionStorage.getItem('operator')||'');if(operator===null)return;await api('/api/delete',{id:b.dataset.delete,password,purpose:reason,operator});if($('modal').open)$('modal').close();await refresh();notice(t('已删除整张误录单据，库存已回滚','The mistaken document was deleted and stock was rolled back'));});return;}
 if(b.dataset.reverse){work(async()=>{const reason=prompt(t('请输入冲销原因。系统将生成反向单据，原单仍保留。','Enter reason. A reversal will be created; the original remains.'));if(!reason)return;const operator=prompt(t('冲销经办人','Reversal operator'),sessionStorage.getItem('operator')||'');if(!operator)return;const res=await api('/api/reverse',{id:b.dataset.reverse,purpose:reason,operator,request_key:crypto.randomUUID()});$('modal').close();await refresh();await showDoc(res.id);notice(t('已生成冲销记录','Reversal posted'));});return;}
 const a=b.dataset.action;
 if(a==='print'){window.print();return;}
 if(a==='admin-password'){work(async()=>{const current=db?.admin_password_configured?prompt(t('请输入当前管理员密码','Enter current administrator password')):'';if(db?.admin_password_configured&&current===null)return;const next=prompt(t('设置新管理员密码（至少6位）','Set a new administrator password (at least 6 characters)'));if(next===null)return;const confirmPassword=prompt(t('再次输入新密码','Enter the new password again'));if(confirmPassword!==next){notice(t('两次密码不一致，未保存','Passwords do not match; nothing was saved'),true);return;}await api('/api/admin-password',{current_password:current||'',new_password:next});await refresh();notice(t('管理员密码已设置','Administrator password saved'));});return;}
 if(a==='delete-post'){work(async()=>{if(!deleteSelected.length)throw Error(t('请先勾选要删除的单据','Select documents to delete first'));if(!db?.admin_password_configured)throw Error(t('请先到单据查询设置管理员密码','Set the administrator password from Documents first'));const operator=$('delete-operator').value,password=$('delete-password').value,purpose=$('delete-purpose').value;if(!window.confirm(t(`确认删除已选择的 ${deleteSelected.length} 张整单？库存会自动回滚。`,`Delete the ${deleteSelected.length} selected document(s)? Stock will be rolled back automatically.`)))return;const res=await api('/api/delete-batch',{ids:deleteSelected,password,purpose,operator});deleteSelected=[];await refresh();notice(t(`已删除 ${res.deleted.length} 张误录单据，库存已回滚`,` ${res.deleted.length} mistaken document(s) deleted; stock rolled back`));});return;}
 if(a==='baseline'){importKind='BASELINE';preview=null;page='inbound';draw();return;}
 work(async()=>{
 if(a==='inspect'){
   validateReceiptPackage();
   if($('file').files[0])upload=await fileData($('file').files[0]);if(!upload)throw Error(t('请先选择文件','Select a file first'));
   preview=await api('/api/preview',payload());
   autoFillReceiptDefaults(preview);
   preview=await api('/api/preview',payload());
   $('sheet').innerHTML=preview.sheets.map(s=>`<option ${s===preview.sheet?'selected':''}>${esc(s)}</option>`).join('');renderPreview();
 }else if(a==='validate'){preview=await api('/api/preview',mappedPayload());renderPreview();
 }else if(a==='import-confirm'){
   validateReceiptPackage();
   const p=mappedPayload();preview=await api('/api/preview',p);renderPreview();if(preview.errors.length)return;
   p.request_key=crypto.randomUUID();sessionStorage.setItem('operator',p.operator);const res=await api('/api/import',p);upload=null;preview=null;page='documents';await refresh();notice(t('已确认，单据和台账已更新','Confirmed. Document and ledger updated.'));await showDoc(res.id);
 }else if(a==='add-selected'){
   addSelectedGroups();$('cart').innerHTML=cartHTML();document.querySelector('[data-action="post"]').disabled=!cart.length;
 }else if(a==='add-cart'){
   const id=Number($('stock-select').value);if(!id)throw Error(t('请选择物资位置','Select a stock position'));if(cart.some(r=>r.stock_id===id))throw Error(t('该位置已在单据中','Position already added'));cart.push({stock_id:id,qty:1});$('cart').innerHTML=cartHTML();document.querySelector('[data-action="post"]').disabled=false;
 }else if(a==='post'){
   const p={kind:action,operator:$('out-operator').value,party:$('out-party').value,purpose:$('out-purpose').value,lines:cart,request_key:outKey,state:$('out-state')?.value,warehouse:$('out-warehouse')?.value,bin:$('out-bin')?.value};sessionStorage.setItem('operator',p.operator);
   const res=await api('/api/post',p);outKey=crypto.randomUUID();cart=[];page='documents';await refresh();notice(t('单据已生成，库存已同步','Document created. Stock synchronized.'));await showDoc(res.id);
 }else if(a==='change-save'){
   await api('/api/change',{code:$('change-code').value,qty:$('change-qty').value,operator:$('change-operator').value,reason:$('change-reason').value,request_key:crypto.randomUUID()});await refresh();notice(t('设计变更已保存，库存未改变','Design change saved. Stock unchanged.'));
 }else if(a==='batch-save'){
   await api('/api/batch',{code:$('batch-code').value,supplier:$('batch-supplier').value,status:$('batch-status').value,operator:$('batch-operator').value,note:$('batch-note').value});await refresh();notice(t('批次状态已保存','Batch status saved'));
 }
 });
});
document.addEventListener('input',e=>{if(e.target.id==='search'||e.target.id==='ledger-search'||e.target.id==='delete-search'){let q=e.target.value.toLowerCase();const selector=e.target.id==='delete-search'?'[data-delete-row]':'[data-search]';document.querySelectorAll(selector).forEach(r=>r.hidden=!r.dataset.search.includes(q));}if(e.target.id==='out-search')applyBulkFilters();if(e.target.dataset.groupQty!==undefined){const check=document.querySelector(`[data-group-check="${e.target.dataset.groupQty}"]`);if(check)check.checked=Number(e.target.value||0)>0;syncBulkCart();}if(e.target.dataset.cart!==undefined)cart[Number(e.target.dataset.cart)].qty=e.target.value;if(['batch-date','batch-number'].includes(e.target.id)){const b=$('batch-preview');if(b)b.textContent=composeBatch()||t('填写批次序号后生成','Enter a batch number to generate');}if(e.target.id==='tree-search'){const pos=e.target.selectionStart;treeState.query=e.target.value;renderInventoryTree();const next=$('tree-search');if(next){next.focus();next.setSelectionRange(pos,pos);}}});
document.addEventListener('change',e=>{const key={'tree-contract':'contract','tree-batch':'batch','tree-warehouse':'warehouse','tree-state':'state','tree-sort':'sort'}[e.target.id];if(key){treeState[key]=e.target.value;renderInventoryTree();}if(e.target.id==='default-package')selectedSegment=e.target.value;if(e.target.id==='out-contract')applyBulkFilters();if(e.target.id==='ledger-kind'){const kind=e.target.value;document.querySelectorAll('[data-ledger-kind]').forEach(r=>r.hidden=!!kind&&r.dataset.ledgerKind!==kind);}if(e.target.dataset.deleteDoc!==undefined)syncDeleteSelection();});
$('lang').addEventListener('click',()=>{lang=lang==='zh'?'en':'zh';localStorage.setItem('materials-language',lang);draw();});
$('refresh').addEventListener('click',()=>work(()=>refresh()));$('close-modal').addEventListener('click',()=>$('modal').close());
boot();

function previewTreeHTML(rows){
 const contracts=treeSort(groupRows(rows,row=>row.package||'未分配标段'),'contract');
 return contracts.length?`<div class="tree preview-tree">${contracts.map(treeContractHtml).join('')}</div>`:empty(t('没有可展示的箱内明细','No item details to display'),t('请先修正识别错误。','Correct the recognition errors first.'));
}
function renderPreview(){
 const r=preview, rows=r.rows||[];
 const sheetKind=r.sheet_kind==='shipment'?t('发货清单（箱级，仅作物流核对）','Shipment list (carton level; logistics reference only)'):t('装箱清单（箱内详件，可办理入库）','Packing detail (carton contents; receipt eligible)');
 $('preview').innerHTML=`<div class="panel"><div class="step-label">02 / ${t('自动识别并核对','AUTO-READ AND VERIFY')}</div><h2>${t('识别结果','Import preview')} · ${r.count} ${t('行','rows')}</h2>${r.errors.length?`<div class="error-list">${r.errors.map(esc).join('\n')}</div>`:`<div class="success-box">${t('自动识别通过。确认后生成单据并一次性入账。','Automatic recognition passed. Confirm to post the document and ledger once.')}<br><b>${esc(sheetKind)}</b> · ${t('工作表','Worksheet')}: ${esc(r.sheet)}</div>`}${r.warnings?.length?`<div class="warning-list">${r.warnings.map(esc).join('\n')}</div>`:''}
 <details class="preview-hierarchy" open><summary>${t('按标段 → 批次 → 箱号 → 箱内物资核对','Verify by lot → batch → box → contents')}</summary><div class="tree-actions"><button class="quiet small" data-preview-toggle="open">${t('全部展开','Expand all')}</button><button class="quiet small" data-preview-toggle="closed">${t('全部收起','Collapse all')}</button></div><div id="preview-tree">${previewTreeHTML(rows)}</div></details>
 <details class="secondary-view"><summary>${t('原始逐行明细（辅助核对）','Original row detail (supporting check)')}</summary>${table([t('源行','Row'),...['code','name','spec','unit','qty','batch','box','warehouse','bin','package','state','attribute'].map(k=>t(...fields[k]))],rows.slice(0,100).map(x=>`<tr><td>${x.source_row}</td>${['code','name','spec','unit','qty','batch','box','warehouse','bin','package'].map(k=>`<td>${esc(x[k])}</td>`).join('')}<td>${badge(x.state)}</td><td>${esc(x.attribute)}</td></tr>`))}</details><p class="helper">${t('系统按固定规则自动匹配表头；箱号相同的行在箱层合并显示，箱内明细逐项保留。确认前可回到上方修改默认批次和库位。','Headers are matched automatically. Rows with the same box are grouped at the box level while every item remains visible. You can change the default batch and location above before confirmation.')}</p><button data-action="import-confirm" ${r.errors.length?'disabled':''}>${importKind==='IN'?t('确认入库并生成入库单','Confirm receipt'):t('确认锁定设计总量','Confirm baseline')}</button></div>`;
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-preview-toggle]');if(!b)return;document.querySelectorAll('#preview-tree details').forEach(d=>d.open=b.dataset.previewToggle==='open');});

function treeLeaf(row){
 const contents=Array.isArray(row.contents)?row.contents:[];
 const childHtml=contents.length?`<div class="tree-contents">${contents.map(c=>`<div>↳ ${c.code?`<span class="code">${esc(c.code)}</span> · `:''}${esc(c.name)} · ${fmt(c.qty)} ${esc(c.unit)}</div>`).join('')}</div>`:'';
 const noteHtml=row.attribute?(contents.length?`<details class="tree-note"><summary>${t('原始备注','Original note')}</summary><div class="sub">${esc(row.attribute)}</div></details>`:`<div class="sub">${esc(row.attribute)}</div>`):'';
 return `<div class="tree-leaf"><div><span class="code">${esc(row.code)}</span><br><span class="name">${esc(row.name)}</span>${row.spec?`<span class="sub"> · ${esc(row.spec)}</span>`:''}${noteHtml}${childHtml}</div><div class="tree-leaf-right"><span>${stockBalanceText(row)}</span>${badge(row.state)}</div></div>`;
}


